// Refuses to run unless the window is explicit and the HIS is accepting writes.
// BCP plan rules 1 and 2: never during an outage, always scoped.
const w = $input.first().json;
if (!w.windowStart || !w.windowEnd) {
  throw new Error('windowStart and windowEnd are required. An unscoped run can duplicate a chart.');
}
if (new Date(w.windowStart) >= new Date(w.windowEnd)) {
  throw new Error('windowStart must be before windowEnd.');
}

// TODO: Replace with a real readiness check against the source HIS.
// Must confirm the HIS is not only up but accepting writes - an HIS still
// replaying its own recovery queue should block this run.
// See docs/api/HIS-RECONCILIATION-CONTRACT.md, capability 7.
const hisWritesAccepted = false;
if (!hisWritesAccepted) {
  throw new Error('HIS readiness check not implemented. Refusing to write.');
}

return [{ json: w }];

// TODO: Implement against the source HIS.
// Capabilities 1 and 2 of docs/api/HIS-RECONCILIATION-CONTRACT.md.
//
// For each BCP temporary patient:
//   1. Match against the HIS on mobile, name + date_of_birth, uhid.
//   2. A confident single match is NOT merged here. Identity merges are
//      always a human decision - emit it as an exception (BCP plan rule 5).
//   3. No match: register in the HIS, idempotency key = the BCP mrn,
//      and record the BCP mrn -> HIS mrn mapping on the item.
//   4. Create a backdated encounter for the new patient (capability 4).
//
// NOTE: the inbound sync workflows reach the source HIS over Postgres,
// not HTTP. Bind this to whichever transport the HIS actually offers.

const dryRun = $('Outage Window').first().json.dryRun;

return $input.all().map(item => ({
  json: {
    kind: 'TEMP_PATIENT',
    bcpMrn: item.json.mrn,
    hisMrn: null,
    outcome: 'EXCEPTION',
    reason: dryRun
      ? 'dry run - no write attempted'
      : 'HIS patient match and register not implemented',
    source: item.json,
  },
}));

// TODO: Implement against the source HIS.
// Capabilities 3, 5 and 6 of docs/api/HIS-RECONCILIATION-CONTRACT.md.
//
// For each note:
//   1. Resolve the target encounter (capability 3), using the mapping
//      produced upstream for temporary patients.
//   2. Write the note with:
//        authoredAt   = created_at, BACKDATED. Not the time of this run.
//        author       = author_full_name + author_role from the note.
//        sourceSystem = 'ATHMA_EDGE_BCP'
//        externalRef  = the note id, also the idempotency key.
//      Losing any of the first three destroys the provenance that made
//      the note worth keeping. See the contract's non-negotiables.
//   3. A note is written back as DOCUMENTATION. Never create an order,
//      prescription or administration record from one, whatever its
//      note_type says (BCP plan rule 4).
//   4. Read back by externalRef and only then call it written (rule 6).

const dryRun = $('Outage Window').first().json.dryRun;

return $input.all().map(item => ({
  json: {
    kind: 'CLINICAL_NOTE',
    bcpNoteId: String(item.json.id),
    mrn: item.json.mrn,
    noteType: item.json.note_type,
    authoredAt: item.json.created_at,
    outcome: 'EXCEPTION',
    reason: dryRun
      ? 'dry run - no write attempted'
      : 'HIS note create not implemented',
    source: item.json,
  },
}));

// BCP plan rule 7: every record ends the run in exactly one of three
// states. Rule 10: this run record is what sign-off is given against.
const w = $('Outage Window').first().json;
const patients = $('Match And Register Patients In HIS').all().map(i => i.json);
const notes = $input.all().map(i => i.json);
const all = patients.concat(notes);

const count = (outcome) => all.filter(r => r.outcome === outcome).length;
const exceptions = all.filter(r => r.outcome === 'EXCEPTION');

if (count('WRITTEN') + count('ALREADY_PRESENT') + exceptions.length !== all.length) {
  throw new Error('Every record must end in exactly one of three states.');
}

return [{
  json: {
    windowStart: w.windowStart,
    windowEnd: w.windowEnd,
    dryRun: w.dryRun,
    ranAt: new Date().toISOString(),
    tempPatients: patients.length,
    clinicalNotes: notes.length,
    written: count('WRITTEN'),
    alreadyPresent: count('ALREADY_PRESENT'),
    exceptions: exceptions.length,
    mrnMapping: patients
      .filter(p => p.hisMrn)
      .map(p => ({ bcpMrn: p.bcpMrn, hisMrn: p.hisMrn })),
    exceptionList: exceptions,
  },
}];

